import fs from 'node:fs';
import cp from 'node:child_process';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {pathToFileURL} from 'node:url';
export const VERSION='notbgg-rc-git-tree-v2';
export const EXCLUSIONS=['docs/notbgg-d7b-deployment-runbook.md','docs/notbgg-deployment-candidate.json'].sort((a,b)=>Buffer.compare(Buffer.from(a),Buffer.from(b)));
export const sha=b=>createHash('sha256').update(b).digest('hex');
export const git=(...args)=>cp.execFileSync('git',args,{stdio:['ignore','pipe','ignore'],maxBuffer:32e6});
export function indexEntries(){return new Map(git('ls-files','--stage','-z').toString().split('\0').filter(Boolean).map(s=>{const [meta,name]=s.split('\t'),[mode,oid,stage]=meta.split(' ');if(stage!=='0')throw Error('Unmerged index');return[name,{mode,oid}];}));}
export function regularMode(mode,indexMode,fileMode){if(indexMode==='120000')throw Error('Symlink changed to regular file');return !fileMode?(indexMode??'100644'):((mode&0o111)?'100755':'100644');}
export function inspect(file,index=indexEntries(),fileMode=git('config','--get','core.filemode').toString().trim()==='true'){
 const st=fs.lstatSync(file,{bigint:true});
 let bytes,mode,oid;
 if(st.isSymbolicLink()){
  bytes=fs.readlinkSync(file,{encoding:'buffer'});mode='120000';
  oid=cp.execFileSync('git',['hash-object','--stdin'],{input:bytes,stdio:['pipe','pipe','ignore']}).toString().trim();
 }else{
  if(!st.isFile())throw Error('Unsupported candidate file type: '+file);
  mode=regularMode(Number(st.mode),index.get(file)?.mode,fileMode);
  bytes=fs.readFileSync(file);
  oid=cp.execFileSync('git',['hash-object','--path='+file,'--stdin'],{input:bytes,stdio:['pipe','pipe','ignore']}).toString().trim();
 }
 return {path:file,gitMode:mode,gitBlobOid:oid,sha256:sha(bytes),bytes:bytes.length,symlink:st.isSymbolicLink(),...(st.isSymbolicLink()?{linkTargetHex:bytes.toString('hex')}:{}),indexAtGeneration:index.get(file)??null};
}
export function payload(manifest,entries){return {algorithm:VERSION,baselineHead:manifest.baselineHead,privateBuildInputSha256:manifest.privateBuildInput.sha256,contentExclusions:EXCLUSIONS,files:[...entries].sort((a,b)=>Buffer.compare(Buffer.from(a.path),Buffer.from(b.path))).map(e=>({path:e.path,gitMode:e.gitMode,gitBlobOid:EXCLUSIONS.includes(e.path)?null:e.gitBlobOid}))};}
export const identify=(manifest,entries)=>sha(Buffer.from(JSON.stringify(payload(manifest,entries)),'utf8'));
const checker=String.raw`const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const m=JSON.parse(fs.readFileSync('docs/notbgg-deployment-candidate.json','utf8'));
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const cmd=(...a)=>cp.execFileSync('git',a,{stdio:['ignore','pipe','ignore']});
const index=new Map(cmd('ls-files','--stage','-z').toString().split('\0').filter(Boolean).map(s=>{const [v,p]=s.split('\t'),[mode,oid]=v.split(' ');return[p,{mode,oid}];}));
const fileMode=cmd('config','--get','core.filemode').toString().trim()==='true';
const exclusions=['docs/notbgg-d7b-deployment-runbook.md','docs/notbgg-deployment-candidate.json'];
const files=[...m.reviewFiles].sort((a,b)=>Buffer.compare(Buffer.from(a.path),Buffer.from(b.path))).map(f=>{
 const st=fs.lstatSync(f.path);let mode,oid;
 if(st.isSymbolicLink()){mode='120000';oid=cp.execFileSync('git',['hash-object','--stdin'],{input:fs.readlinkSync(f.path,{encoding:'buffer'}),stdio:['pipe','pipe','ignore']}).toString().trim();}
 else {if(!st.isFile()||index.get(f.path)?.mode==='120000')throw Error('STOP: file type changed');mode=fileMode?((st.mode&0o111)?'100755':'100644'):(index.get(f.path)?.mode||'100644');if(!exclusions.includes(f.path))oid=cp.execFileSync('git',['hash-object','--path='+f.path,'--stdin'],{input:fs.readFileSync(f.path),stdio:['pipe','pipe','ignore']}).toString().trim();}
 if(mode!==f.gitMode||(!exclusions.includes(f.path)&&oid!==f.gitBlobOid))throw Error('STOP: mode/blob changed: '+f.path);
 return {path:f.path,gitMode:mode,gitBlobOid:exclusions.includes(f.path)?null:oid};
});
if(sha(fs.readFileSync(m.privateBuildInput.path))!==m.privateBuildInput.sha256)throw Error('STOP: private build input changed');
const p={algorithm:'notbgg-rc-git-tree-v2',baselineHead:m.baselineHead,privateBuildInputSha256:m.privateBuildInput.sha256,contentExclusions:exclusions,files};
const id=sha(Buffer.from(JSON.stringify(p),'utf8'));
if(m.algorithmVersion!=='notbgg-rc-git-tree-v2'||id!==m.candidateSourceId||id!==process.env.NOTBGG_EXPECTED_SOURCE_ID)throw Error('STOP: candidate identity mismatch');
console.log('CANDIDATE_CONTENT_PASS '+id);`;
export async function generate(){
 const snap=JSON.parse(fs.readFileSync('.wrangler/release-candidate-final/start-snapshot.json'));
 const old=snap.candidate,m=structuredClone(old),approved=m.plannedCommits.flatMap(x=>x.files);
 if(JSON.stringify(m.plannedCommits.map(x=>x.files.length))!=='[1,116,103]'||approved.length!==220||new Set(approved).size!==220)throw Error('Candidate scope differs');
 if(m.deltaFiles.some(x=>!approved.includes(x))||m.excludedFiles.length!==18)throw Error('Delta/exclusion differs');
 if(git('rev-parse','HEAD').toString().trim()!==snap.head||git('ls-files','--stage','-z').toString()!==snap.index)throw Error('HEAD/index changed before generation');
 const allowed=new Set(EXCLUSIONS.concat(['.wrangler/rate-limiter-fix/freeze.mjs','.wrangler/rate-limiter-fix/identity.mjs']));
 for(const row of snap.rows){const st=fs.lstatSync(row.path,{bigint:true});if(row.symlink){const b=fs.readlinkSync(row.path,{encoding:'buffer'});if(!st.isSymbolicLink()||b.toString('hex')!==row.linkTargetHex||st.ino.toString()!==row.ino)throw Error('Existing symlink changed: '+row.path);}else if(!allowed.has(row.path)&&sha(fs.readFileSync(row.path))!==row.sha256)throw Error('Unexpected round change: '+row.path);}
 const index=indexEntries(),entries=m.reviewFiles.map(f=>inspect(f.path,index));
 for(const e of entries){const prior=old.reviewFiles.find(f=>f.path===e.path);if(!e.symlink&&!EXCLUSIONS.includes(e.path)&&(e.sha256!==prior.sha256||e.gitBlobOid!==prior.gitBlobOid))throw Error('Unapproved candidate change: '+e.path);if(!approved.includes(e.path)&&(!index.has(e.path)||index.get(e.path).mode!==e.gitMode||index.get(e.path).oid!==e.gitBlobOid))throw Error('Inherited worktree/index mismatch: '+e.path);}
 const links=entries.filter(e=>e.symlink);const claude=links.find(e=>e.path==='CLAUDE.md');if(!claude||claude.gitBlobOid!=='47dc3e3d863cfb5727b87d785d09abf9743c0a72'||claude.gitMode!=='120000')throw Error('CLAUDE mismatch');
 for(const [f,h]of Object.entries(m.migrationSha256))if(sha(fs.readFileSync('migrations/'+f))!==h)throw Error('Migration changed: '+f);
 if(sha(fs.readFileSync('src/data/bgg-cache.json'))!=='1e345be12cf66b871f0267af622445d50ba1120ba98181ca2390dadc0da82f91')throw Error('BGG changed');
 if(sha(fs.readFileSync(m.privateBuildInput.path))!==m.privateBuildInput.sha256)throw Error('Private build input changed');
 for(const e of m.excludedFiles)if(sha(fs.readFileSync(e.path))!==e.sha256)throw Error('Excluded original changed');
 const id=identify(m,entries);if(id===old.candidateSourceId)throw Error('Old invalid ID reused');
 let book=fs.readFileSync('docs/notbgg-d7b-deployment-runbook.md','utf8').replaceAll(old.candidateSourceId,id);
 book=book.replace(/這個識別由[^\n]+/,'此識別使用notbgg-rc-git-tree-v2：完整候選樹按UTF-8路徑bytes排序，記錄path、六位Git mode、Git Blob OID。符號連結以lstat/readlink讀取target原始bytes、mode120000，不解參照；一般檔按Git clean filter及filemode規則。Manifest與Runbook仍在220項中，其內容OID在識別payload設null，路徑/mode仍納入，避免循環。');
 const start=book.indexOf('候選 manifest 核對命令'),end=book.indexOf('完成**所有管理寫入入口的停寫**',start);if(start<0||end<0)throw Error('Checker section missing');
 book=book.slice(0,start)+'候選manifest v2核對命令（唯讀、symlink-aware；不寫Git object）：\n\n~~~powershell\n$env:NOTBGG_EXPECTED_SOURCE_ID = $NotBggExpectedSourceId\n'+"@'\n"+checker+"\n'@ | node\n"+"if ($LASTEXITCODE -ne 0) { throw 'STOP: candidate changed' }\n~~~\n\n"+book.slice(end);
 const rule='\n### 候選識別演算法 v2（本輪核准修正）\n\n'+
 '演算法版本：`notbgg-rc-git-tree-v2`。以完整預計Git tree（280路徑；220提交項＋60繼承基線）為輸入，不只取非docs檔。canonical JSON依序keys為algorithm、baselineHead、privateBuildInputSha256、contentExclusions、files；files每項keys依序path、gitMode、gitBlobOid。路徑使用repo-relative POSIX字串，按UTF-8 bytes升序；mode為100644/100755/120000六位字串，OID為Git SHA-1小寫hex。JSON為UTF-8、無BOM、compact、無結尾換行，再SHA256。\n\n'+
 'contentExclusions固定按UTF-8排序為`docs/notbgg-d7b-deployment-runbook.md`與`docs/notbgg-deployment-candidate.json`；僅把兩者的內容gitBlobOid設null，其path/mode仍保留。兩份檔案均照原清單提交，不移出220項。其餘278項的內容（包含所有其他docs及繼承基線）全部納入。一般檔用git hash-object --path=<path> --stdin計clean Blob；連結僅readlink的raw bytes交git hash-object --stdin，不套filter、不補換行。\n\n'+
 'Git core.filemode=false時一般檔沿用既有Index的regular mode，新檔預設100644；true時依執行位元100755/100644。lstat的連結型別必須與Index區分，禁止以Index Blob替代工作樹檢查。CLAUDE.md必須為120000／47dc3e3d863cfb5727b87d785d09abf9743c0a72。\n\n'+
 '本機產生器位於ignored `.wrangler/release-candidate-final/generator.mjs`；屬本次任務工具，不加入220範圍，非新增正式工具入口。其完整來源與SHA256嵌入Manifest中繼資料；Runbook提供不依賴ignored工具的唯讀checker，另以獨立Python程序重算。\n\n'+
 '舊識別`'+old.candidateSourceId+'`因連結處理錯誤已廢止，不可用於最後RC。其他舊算法證據只作歷史基線。本Manifest/Runbook為提交前凍結記錄，actualDeploymentCommit維持生成時null；三個實際SHA另存本機Git及ignored操作收據，不為回填SHA增加第4個Commit或amend。\n';
 const marker='### 0003／Migration／F1／F2';if(!book.includes(marker))throw Error('Rule insertion marker missing');book=book.replace(marker,rule+'\n'+marker);
 fs.writeFileSync('docs/notbgg-d7b-deployment-runbook.md',book);
 const finalEntries=m.reviewFiles.map(f=>inspect(f.path,index));m.algorithmVersion=VERSION;m.previousInvalidCandidateSourceId=old.candidateSourceId;m.candidateSourceId=id;m.identityDefinition='See identityAlgorithm: all prospective tree paths/modes/OIDs, metadata content null, compact UTF-8 JSON SHA256';m.identityAlgorithm={version:VERSION,payloadKeyOrder:['algorithm','baselineHead','privateBuildInputSha256','contentExclusions','files'],entryKeyOrder:['path','gitMode','gitBlobOid'],pathOrder:'UTF-8 bytewise ascending; repo-relative POSIX',encoding:'UTF-8 compact JSON, no BOM or trailing newline; literal Unicode',gitBlobAlgorithm:'sha1',metadataContentExclusions:EXCLUSIONS,metadataStillSubmitted:true,privateInput:'hash only; ignored private input not added to Git',symlinkRule:'lstat/readlink raw target bytes; mode120000; no filters, dereference or appended newline',regularModeRule:'Git core.filemode; index regular mode retained when false, new regular files100644',treeEntries:finalEntries.length,contentEntries:finalEntries.length-2};
 m.reviewFiles=finalEntries.map(e=>e.path==='docs/notbgg-deployment-candidate.json'?{...e,gitBlobOid:null,sha256:null,bytes:null,reason:'metadata self-content excluded; exact staged/committed Blob captured in external receipt'}:e);
 m.identityPayload=payload(m,finalEntries);m.symlinkValidation=links;m.generator={role:snap.generatorRole,path:'.wrangler/release-candidate-final/generator.mjs',sha256:sha(fs.readFileSync('.wrangler/release-candidate-final/generator.mjs')),source:fs.readFileSync('.wrangler/release-candidate-final/generator.mjs','utf8'),reproduce:'Source saved as ignored local task script; Runbook checker is standalone. Do not add generator to the220 paths.'};m.status='Corrected v2 candidate; local commits allowed only after independent verification';m.actualDeploymentCommit=null;m.reviewManifestSha256=sha(Buffer.from(JSON.stringify(m.reviewFiles.map(e=>({path:e.path,gitMode:e.gitMode,gitBlobOid:e.gitBlobOid})))));m.gitReceiptLocation='.wrangler/release-candidate-final/commits.json';
 if(identify(m,finalEntries)!==id)throw Error('Metadata update changed identity');fs.writeFileSync('docs/notbgg-deployment-candidate.json',JSON.stringify(m,null,2)+'\n');
 const expected=m.reviewFiles.map(e=>inspect(e.path,index));fs.writeFileSync('.wrangler/release-candidate-final/expected-tree.json',JSON.stringify({candidateId:id,baseline:snap.head,entries:expected,symlinks:links,groups:m.plannedCommits,contentExclusions:EXCLUSIONS,manifestSha256:sha(fs.readFileSync('docs/notbgg-deployment-candidate.json'))},null,2));console.log(JSON.stringify({candidateId:id,groups:m.plannedCommits.map(x=>x.files.length),treeEntries:expected.length,links:links.map(e=>({path:e.path,mode:e.gitMode,blob:e.gitBlobOid}))}));return m;
}
if(process.argv[1]&&pathToFileURL(path.resolve(process.argv[1])).href===import.meta.url&&process.argv[2]==='--generate')await generate();
